revise(29,topic='切片内表格格式',stem='同一表格内容可存为Markdown或HTML切片，团队更看重降低Token消耗；官方文档给出的取舍是哪项？',options={'A':'HTML通常消耗更少Token，Markdown通常效果更好','B':'Markdown必定同时具有更低Token消耗和更好效果','C':'两种格式只改变展示，不影响Token消耗','D':'HTML只支持图片，不能表示切片内表格'},answer=['A'],explanation='文档支持将切片内表格设置为Markdown或HTML；其经验说明是Markdown效果更好、HTML消耗Token较少。因此按题设优先考虑HTML，并仍应实测质量。',distractors={'B':'官方将效果与Token优势分别描述，不能同时归给Markdown。','C':'文档明确提及Token消耗差异。','D':'HTML正是列明的表格切片格式。'})
