revise(51,topic='知识问答问题与提示词分工',stem='大模型知识问答节点中，开发者将“按三列表格回复”填入用户问题，却把本轮业务问题仅放入中间消息，导致检索偏离。哪项修改最直接？',options={'A':'只增加中间消息的展示长度','B':'只修改输出格式，不设置检索问题','C':'将业务问题配置到用户问题，将表格回复要求放入提示词','D':'将格式要求重复写入用户问题以提高其权重'},answer=['C'],explanation='用户问题是实际用于检索回答的提问内容；提示词可补充输出格式、排序和回复限制。中间消息用于缓解等待，不能替代检索问题配置。应将业务查询与格式约束放入各自对应字段。',distractors={'A':'中间消息是等待时的展示，不承担检索查询字段职责。','B':'生成格式不能补齐被错误配置的业务查询。','D':'加强格式描述仍未把真实业务查询交给检索。'})
